/*
 * <houston-loader>: the Houston mark as a loader. Pack v0.4.0.
 *
 * Generated by design-system/scripts/build.py from brand/source/geometry.json. Do not edit:
 * change the template in scripts/templates/ or the numbers in geometry.json, then rebuild.
 *
 * The mark is drawn exactly as shipped (mark D). Only the teal dot moves. It travels the ring
 * clockwise and always comes back to rest where the logo has it, so at rest the loader is the logo.
 *
 *   <houston-loader></houston-loader>                    orbit: a wait of unknown length (default)
 *   <houston-loader variant="comet"></houston-loader>    orbit at an even pace, with a fading trail
 *   <houston-loader variant="arrival"></houston-loader>  one orbit, then rest (page load, logo reveal)
 *   <houston-loader value="42"></houston-loader>         progress, 0 to 100
 *
 * Size: CSS width and height (default 48px, minimum 16px).
 * Colours: follows --ox-color-text and --ox-color-accent when the pack's variables.css is loaded.
 *          Override with --houston-ink and --houston-accent.
 * Name:    label="..." sets the accessible name (default "Loading").
 * Motion:  respects prefers-reduced-motion. The timings are fixed.
 * Methods: replay() restarts the arrival.
 *
 * Copyright (c) 2026 Orvex AI Ltd. Code: MIT. The Houston mark is a trademark and is not
 * covered by the code licence. See design-system/LICENSE.md.
 */
(() => {
  if (typeof customElements === 'undefined' || customElements.get('houston-loader')) return;

  // The mark's geometry and the motion timings, written in by the build.
  const M = {"frame":{"x":2.25,"y":2.25,"size":43.5,"rx":10.75,"stroke":4.5},"ring":{"r":12.75,"stroke":4.5},"dot":{"x":15,"y":33,"r":6,"angle":135},"ink":"#f1f5f9","accent":"#23b5d1","orbit":{"duration":1.6,"ease":[0.65,0,0.35,1]},"comet":{"duration":1.6,"trailDegrees":120,"trailSteps":6},"arrival":{"duration":1.2,"ease":[0.65,0,0.35,1]},"progress":{"transition":0.35,"ease":[0.33,0,0.2,1],"hold":0.45,"fade":0.6},"reduced":{"duration":1.2,"opacity":0.35}};

  const C = 2 * Math.PI * M.ring.r; // circumference of the ring
  const N = (value) => String(Math.round(value * 1000) / 1000);
  const ease = (curve) => `cubic-bezier(${curve.join(',')})`;
  const ink = `var(--houston-ink,var(--ox-color-text,${M.ink}))`;
  const accent = `var(--houston-accent,var(--ox-color-accent,${M.accent}))`;
  const reduced = (host) => `
${host} .orbit .spin,${host} .comet .spin{animation:rest ${M.reduced.duration}s ease-in-out infinite alternate}
${host} .comet .trail{display:none}
${host} .arrival .spin{animation:none}
${host} .progress .spin,${host} .progress .arc{transition:none}`;

  // Only .spin (the dot and its trail) and .arc (the progress arc) are ever animated.
  const css = `
:host{display:inline-block;width:48px;height:48px;vertical-align:middle}
:host([hidden]){display:none}
svg{display:block;width:100%;height:100%;overflow:visible}
.ink{fill:none;stroke:${ink}}
.dot{fill:${accent}}
.trail circle,.arc{fill:none;stroke:${accent};stroke-width:${M.ring.stroke}}
.spin{transform-box:view-box;transform-origin:24px 24px}
.orbit .spin{animation:orbit ${M.orbit.duration}s ${ease(M.orbit.ease)} infinite}
.comet .spin{animation:orbit ${M.comet.duration}s linear infinite}
.arrival .spin{animation:orbit ${M.arrival.duration}s ${ease(M.arrival.ease)} 1 both}
.progress .spin{transition:transform ${M.progress.transition}s ${ease(M.progress.ease)}}
.progress .arc{transition:stroke-dasharray ${M.progress.transition}s ${ease(M.progress.ease)},opacity ${M.progress.fade}s ease}
.progress.done .arc{opacity:0}
.reset .spin,.reset .arc{transition:none!important}
@keyframes orbit{to{transform:rotate(360deg)}}
@keyframes rest{from{opacity:1}to{opacity:${M.reduced.opacity}}}
@media (prefers-reduced-motion:reduce){${reduced(':host')}
}${reduced(':host([data-reduced])')}
@media (forced-colors:active){.ink{stroke:CanvasText}.dot{fill:Highlight}.trail circle,.arc{stroke:Highlight}}`;

  // One shared stylesheet. Constructed sheets also work under a strict Content-Security-Policy.
  let sheet = null;
  try { sheet = new CSSStyleSheet(); sheet.replaceSync(css); } catch (error) { sheet = null; }

  const f = M.frame;
  const dot = `<circle class="dot" cx="${M.dot.x}" cy="${M.dot.y}" r="${M.dot.r}"/>`;
  const mark = (inner) =>
    `<svg viewBox="0 0 48 48" aria-hidden="true" focusable="false">` +
    `<rect class="ink" x="${f.x}" y="${f.y}" width="${f.size}" height="${f.size}" rx="${f.rx}" stroke-width="${f.stroke}"/>` +
    `<circle class="ink" cx="24" cy="24" r="${M.ring.r}" stroke-width="${M.ring.stroke}"/>${inner}</svg>`;

  // Trail behind the dot: stacked arcs that all end at the dot, so the teal builds towards it.
  const trail = () => {
    const steps = M.comet.trailSteps;
    let arcs = '';
    for (let i = 1; i <= steps; i++) {
      const degrees = (M.comet.trailDegrees * i) / steps;
      arcs += `<circle cx="24" cy="24" r="${M.ring.r}" stroke-dasharray="${N((C * degrees) / 360)} ${N(C)}"` +
        ` transform="rotate(${N(M.dot.angle - degrees)} 24 24)" opacity="${N(1 / steps)}"/>`;
    }
    return `<g class="trail">${arcs}</g>`;
  };

  class HoustonLoader extends HTMLElement {
    static get observedAttributes() { return ['value', 'variant', 'label']; }

    constructor() {
      super();
      this.attachShadow({ mode: 'open' });
      this._p = 0;
    }

    connectedCallback() { this.render(); }

    disconnectedCallback() { clearTimeout(this._doneTimer); }

    attributeChangedCallback(name) {
      if (!this._box) return;
      if (name === 'label') this.setAttribute('aria-label', this.label);
      else if (name === 'value' && this.hasAttribute('value') && this._mode === 'progress') this.update();
      else this.render();
    }

    get label() { return this.getAttribute('label') || 'Loading'; }

    get mode() {
      if (this.hasAttribute('value')) return 'progress';
      const variant = this.getAttribute('variant');
      return variant === 'comet' || variant === 'arrival' ? variant : 'orbit';
    }

    /** Restart the animation from rest. Useful for the arrival. */
    replay() { this.render(); }

    render() {
      clearTimeout(this._doneTimer);
      this._mode = this.mode;
      let inner = `<g class="spin head">${dot}</g>`;
      if (this._mode === 'comet') inner = `<g class="spin">${trail()}${dot}</g>`;
      if (this._mode === 'progress') {
        inner = `<circle class="arc" cx="24" cy="24" r="${M.ring.r}" transform="rotate(${M.dot.angle} 24 24)"` +
          ` stroke-dasharray="0 ${N(C)}"/>` + inner;
      }
      const root = this.shadowRoot;
      root.innerHTML = `<div class="${this._mode}">${mark(inner)}</div>`;
      if (sheet && 'adoptedStyleSheets' in root) root.adoptedStyleSheets = [sheet];
      else root.insertAdjacentHTML('afterbegin', `<style>${css}</style>`);
      this._box = root.querySelector('div');
      if (this._mode === 'progress') {
        this.setAttribute('role', 'progressbar');
        this.setAttribute('aria-valuemin', '0');
        this.setAttribute('aria-valuemax', '100');
        this._p = 0;
        this.update(true);
      } else {
        this.setAttribute('role', 'status');
        ['aria-valuemin', 'aria-valuemax', 'aria-valuenow'].forEach((name) => this.removeAttribute(name));
      }
      this.setAttribute('aria-label', this.label);
    }

    update(instant) {
      const raw = parseFloat(this.getAttribute('value'));
      const p = Math.min(1, Math.max(0, Number.isFinite(raw) ? raw / 100 : 0));
      const box = this._box;
      const arc = box.querySelector('.arc');
      const head = box.querySelector('.head');
      const backwards = p < this._p - 1e-6;
      const filling = !instant && p > this._p + 1e-6;
      this.setAttribute('aria-valuenow', String(Math.round(p * 100)));
      if (!instant && !backwards && !filling) return; // the same value again: nothing changes
      if (instant || backwards) box.classList.add('reset');
      box.classList.remove('done');
      clearTimeout(this._doneTimer);
      arc.setAttribute('stroke-dasharray', `${N(C * p)} ${N(C)}`);
      head.style.transform = `rotate(${N(360 * p)}deg)`;
      if (instant || backwards) { void box.offsetWidth; box.classList.remove('reset'); }
      // At 100% the ring is fully teal for the hold time, counted from the end of the fill.
      // Then the arc fades and the mark is at rest. (With reduced motion the fill takes no time.)
      if (p >= 1) {
        const fill = filling ? parseFloat(getComputedStyle(head).transitionDuration) || 0 : 0;
        this._doneTimer = setTimeout(() => box.classList.add('done'), (fill + M.progress.hold) * 1000);
      }
      this._p = p;
    }
  }

  customElements.define('houston-loader', HoustonLoader);
})();
